create.PArg.sql:
CREATE FUNCTION MborobakProbe.PArg(s VARCHAR(100)) RETURNS VARCHAR(100) LANGUAGE OBJECTSCRIPT {
 quit $select(s="":"<null>",s=$c(0):"<c0>",1:"len "_$length(s))
}

create.PFind.sql:
CREATE FUNCTION MborobakProbe.PFind(s VARCHAR(100), p VARCHAR(100)) RETURNS INT LANGUAGE OBJECTSCRIPT {
 quit:s="" "" quit $locate($select(s=$c(0):"",1:s),p)>0
}

create.PNew.sql:
CREATE FUNCTION MborobakProbe.PNew(s VARCHAR(100), p VARCHAR(100)) RETURNS INT LANGUAGE OBJECTSCRIPT {
 set m=##class(%Regex.Matcher).%New(p,$select(s=$c(0):"",1:s)) quit m.Locate()
}

create.PCached.sql:
CREATE FUNCTION MborobakProbe.PCached(s VARCHAR(100), p VARCHAR(100)) RETURNS INT LANGUAGE OBJECTSCRIPT {
 if $get(%pRx("p"))'=p { set %pRx("m")=##class(%Regex.Matcher).%New(p), %pRx("p")=p }
 set m=%pRx("m"), m.Text=$select(s=$c(0):"",1:s) quit m.Locate()
}

create.PRepl.sql:
CREATE FUNCTION MborobakProbe.PRepl(s VARCHAR(100), p VARCHAR(100), r VARCHAR(100)) RETURNS VARCHAR(100) LANGUAGE OBJECTSCRIPT {
 quit:s="" "" set m=##class(%Regex.Matcher).%New(p,$select(s=$c(0):"",1:s)) quit m.ReplaceAll(r)
}
